{"sql": "CREATE VIEW IF NOT EXISTS credit_health_calculator AS
SELECT
  (0.4 * MIN(1.0, CAST(800 AS REAL) / 850)
   + 0.2 * MIN(1.0, 1 - CAST(0.2 AS REAL))
   + 0.2 * MIN(1.0, 1 - CAST(0.3 AS REAL))
   + 0.1 * MIN(1.0, CAST(15 AS REAL) / 20)
   + 0.1 * MIN(1.0, 1 - (CAST(0 AS REAL) + CAST(0 AS REAL) + CAST(0 AS REAL) + CAST(0 AS REAL)) / 10)
  ) AS sample_credit_health_score;
SELECT * FROM credit_health_calculator;"}

