{"sql": "CREATE TABLE IF NOT EXISTS battery_efficiency_enum (classification TEXT);
INSERT INTO battery_efficiency_enum (classification) VALUES ('Excellent Efficiency'), ('Good Efficiency'), ('Average Efficiency'), ('Poor Efficiency');
CREATE VIEW IF NOT EXISTS classify_battery_efficiency AS
SELECT d.devregistry AS device_id,
       (t.battlifeh * t.battcapmah) / (d.pwractmw * 10.0) AS ber,
       CASE
         WHEN (t.battlifeh * t.battcapmah) / (d.pwractmw * 10.0) > 7.5 THEN 'Excellent Efficiency'
         WHEN (t.battlifeh * t.battcapmah) / (d.pwractmw * 10.0) >= 5.0 AND (t.battlifeh * t.battcapmah) / (d.pwractmw * 10.0) <= 7.5 THEN 'Good Efficiency'
         WHEN (t.battlifeh * t.battcapmah) / (d.pwractmw * 10.0) >= 2.5 AND (t.battlifeh * t.battcapmah) / (d.pwractmw * 10.0) <= 4.9 THEN 'Average Efficiency'
         ELSE 'Poor Efficiency'
       END AS efficiency_classification
FROM deviceidentity d
JOIN testsessions t ON d.devsessionref = t.sessionregistry
WHERE d.conntype IN ('Bluetooth', 'Wireless 2.4GHz');
SELECT * FROM battery_efficiency_enum;
SELECT COUNT(*) AS total, COUNT(DISTINCT device_id) AS devices FROM classify_battery_efficiency;
SELECT efficiency_classification, COUNT(*) AS cnt FROM classify_battery_efficiency GROUP BY efficiency_classification;"}

