{"sql": "WITH rf AS (
  SELECT fackey FROM facilities
  WHERE CASE json_extract(support_and_resources, '$.community_resources')
          WHEN 'Comprehensive' THEN 3 WHEN 'Adequate' THEN 2 ELSE 1 END >= 2
)
SELECT COUNT(*) AS rf_count FROM rf;
SELECT COUNT(DISTINCT c.facconnect) AS rf_with_clinicians FROM clinicians c JOIN rf ON c.facconnect = rf.fackey;
SELECT COUNT(DISTINCT c2.facconnect) AS rf_with_patients
FROM clinicians c2
JOIN rf ON c2.facconnect = rf.fackey
JOIN patients p ON p.clinleadref = c2.clinkey;"}

