SELECT COUNT(*) AS expected FROM assessmentbasics ab JOIN assessmentsymptomsandrisk asr ON ab.abkey = asr.asrkey WHERE asr.suicrisk IN ('High','Severe') OR CAST(json_extract(asr.mental_health_scores,'$.depression.phq9_score') AS INTEGER) > 15 OR CAST(json_extract(asr.mental_health_scores,'$.anxiety.gad7_score') AS INTEGER) > 15;"}

