{"sql": "WITH cpi AS (
  SELECT a.artregistry, a.artdynasty, a.conservestatus,
         ((ar.histsignrating + ar.researchvalrating + ar.cultscore) * (10.0 - CASE TRIM(a.conservestatus) WHEN 'Excellent' THEN 1 WHEN 'Good' THEN 3 WHEN 'Fair' THEN 5 WHEN 'Poor' THEN 7 WHEN 'Critical' THEN 10 END)) / 30.0 AS cpi
  FROM artifactscore a
  JOIN artifactratings ar ON TRIM(ar.artref) = TRIM(a.artregistry)
)
SELECT artdynasty, COUNT(*) AS n, ROUND(AVG(cpi),4) AS avg_cpi, ROUND(SUM(cpi),2) AS sum_cpi, ROUND(MIN(cpi),4) AS min_cpi, ROUND(MAX(cpi),2) AS max_cpi FROM cpi GROUP BY artdynasty;
