{"sql": "SELECT MIN(engrate), MAX(engrate), AVG(engrate), MIN(socintscore), MAX(socintscore), MIN(actdayswk), MAX(actdayswk), MIN(avgsesscount), MAX(avgsesscount) FROM engagement;
SELECT MIN(intconsist), MAX(intconsist), MIN(lastlogdt), MAX(lastlogdt) FROM preferencesandsettings;
SELECT MIN(spendusd), MAX(spendusd), MIN(membdays), MAX(membdays) FROM membershipandspending;
SELECT MIN(gifttot), MAX(gifttot) FROM interactions;
SELECT churnflag, COUNT(*) FROM retentionandinfluence GROUP BY churnflag;
SELECT lastlogdt FROM preferencesandsettings LIMIT 5;"}

{"sql": "SELECT cnt, COUNT(*) AS fans
FROM (
  SELECT interactfanpivot, COUNT(*) cnt FROM interactions GROUP BY interactfanpivot
) GROUP BY cnt ORDER BY cnt;"}

{"sql": "SELECT mult, COUNT(*) AS fan_count FROM (
  SELECT f.userregistry, COUNT(i.activityreg) AS mult
  FROM fans f
  LEFT JOIN interactions i ON i.interactfanpivot = f.userregistry
  GROUP BY f.userregistry
) GROUP BY mult ORDER BY mult;"}

{"sql": "SELECT mult, COUNT(*) AS fan_count FROM (
  SELECT f.userregistry, COUNT(m.memberreg) AS mult
  FROM fans f
  LEFT JOIN membershipandspending m ON m.memberfanpivot = f.userregistry
  GROUP BY f.userregistry
) GROUP BY mult ORDER BY mult;"}

{"sql": "SELECT COUNT(*) AS cand_count FROM retentionandinfluence r
JOIN engagement e ON r.retainengagepivot = e.engagereg
JOIN membershipandspending m ON e.engagememberpivot = m.memberreg
JOIN preferencesandsettings p ON p.preferencesmemberpivot = m.memberreg
WHERE (1 - p.intconsist) * 2 + ((julianday('2025-04-20') - julianday(p.lastlogdt)) / 30) * 0.5
      + (CASE r.churnflag WHEN 'None' THEN 0 WHEN 'Low' THEN 1 WHEN 'Medium' THEN 2 WHEN 'High' THEN 3 END / 3.0) * 2 > 3.5
  AND julianday('2025-04-20') - julianday(p.lastlogdt) > 20
  AND e.engrate < 0.2;

SELECT COUNT(*) AS total_fans FROM fans;
SELECT COUNT(*) AS total_ret FROM retentionandinfluence;
SELECT COUNT(*) AS total_members FROM membershipandspending;"}

{"sql": "SELECT COUNT(*) AS low_engrate FROM engagement WHERE engrate < 0.2;
SELECT COUNT(DISTINCT f.userregistry) AS joined_fans FROM retentionandinfluence r
JOIN engagement e ON e.engagereg = r.retainengagepivot
JOIN membershipandspending m ON m.memberreg = e.engagememberpivot
JOIN fans f ON f.userregistry = m.memberfanpivot
JOIN preferencesandsettings p ON p.preferencesmemberpivot = m.memberreg;"}

